import { mimeForExtension } from "../../packages/core/index";
import { Hono } from "hono";
import { build } from "../../container";
import { notFound } from "../errors";
import type { ApiEnv } from "../types";

/** Keys generated by the image stores: ULID (Crockford) + allowed extension. Anything else is 404. */
const VALID_KEY = /^[0-9A-HJKMNP-TV-Z]{26}\.(jpg|png|webp)$/;

export const imgRoutes = new Hono<ApiEnv>().get("/:key", async (c) => {
  const key = c.req.param("key");
  const extension = VALID_KEY.exec(key)?.[1];
  // The content-type comes from the (already validated) extension, never from stored metadata.
  const type = extension === undefined ? undefined : mimeForExtension(extension);
  if (type === undefined) return notFound(c);
  const image = await build(c.env).images.read(key);
  if (image === null) return notFound(c);
  const headers = new Headers();
  headers.set("content-type", type);
  // Defense in depth: the browser must not "guess" another type or run anything on this origin.
  headers.set("x-content-type-options", "nosniff");
  headers.set("content-security-policy", "default-src 'none'");
  // The key is immutable (a new ULID per uploaded image): it identifies the content and can be cached forever.
  headers.set("etag", `"${key}"`);
  headers.set("cache-control", "public, max-age=31536000, immutable");
  return new Response(image.bytes as Uint8Array<ArrayBuffer>, { headers });
});
